bool cNetGameServer::isUnreadMail(CMailInfo* pInfo) {
    if (pInfo != nullptr) {
        if (pInfo->m_ucState != 2) {
            return static_cast<bool>((static_cast<unsigned long>(pInfo->m_ucItemState) & static_cast<unsigned long>((pInfo->m_ucItemState & 254) != 0)) & 1ul);
        } else {
            return true;
        }
    } else {
        return false;
    }
}

